/* Original procedural 3D illustration. Fixed illustrative speed, never physiological inference. */
window.FlowScene=(()=>{
 const instances=new Set(),tr=(en,ar)=>document.documentElement.lang==='ar'?ar:en;
 function create(host,options={}){
  const box=document.createElement('section');box.className='flow-scene';
  box.innerHTML='<div class="flow-head"><strong></strong><span></span></div><div class="vessel-modes"><button type="button" data-mode="open">Without narrowing</button><button type="button" data-mode="narrow">Illustrative narrowing</button></div><div class="vessel-stage"><span class="vessel-callout"></span></div><div class="flow-direction" aria-hidden="true">→ → → → →</div><div class="flow-controls"><button type="button" class="secondary"></button><label><span></span><input type="range" min="-30" max="30" value="0"></label></div><p></p>';
  host.append(box);const stage=box.querySelector('.vessel-stage'),button=box.querySelector('.flow-controls button'),slider=box.querySelector('input');
  let narrowed=false,wall,base,pointer;let renderer,scene,camera,group,cells=[],material,frame=0,preview=false,playing=false,frozen=matchMedia('(prefers-reduced-motion: reduce)').matches,time=0,signal=0,last=0,disposed=false;
  try{
   renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(900,430,false);renderer.outputColorSpace=THREE.SRGBColorSpace;stage.append(renderer.domElement);
   renderer.domElement.setAttribute('role','img');
   scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(35,900/430,.1,100);camera.position.set(0,1.3,12);camera.lookAt(0,0,0);group=new THREE.Group();scene.add(group);
   scene.add(new THREE.HemisphereLight(0xffffff,0x493530,2.4));const light=new THREE.DirectionalLight(0xffe5cf,3);light.position.set(-3,6,6);scene.add(light);const rim=new THREE.DirectionalLight(0xffffff,1.7);rim.position.set(4,-2,-2);scene.add(rim);
   // A cutaway cylinder exposes its interior rather than hiding cells behind a transparent tube.
   wall=new THREE.Mesh(new THREE.CylinderGeometry(1.15,1.15,8,64,64,true,Math.PI*.15,Math.PI*1.25),new THREE.MeshStandardMaterial({color:0xb7706f,roughness:.55,metalness:.08,side:THREE.DoubleSide}));wall.rotation.z=Math.PI/2;wall.rotation.x=.25;group.add(wall);base=wall.geometry.attributes.position.array.slice();pointer=new THREE.ArrowHelper(new THREE.Vector3(0,-1,0),new THREE.Vector3(0,2.1,0),1.4,0xf2b766,.23,.14);pointer.visible=false;group.add(pointer);
   material=new THREE.MeshStandardMaterial({color:0xc64246,roughness:.38,metalness:.06,emissive:0x482014,emissiveIntensity:0});
   const profile=[];for(let i=0;i<=24;i++){const a=i/24*Math.PI;profile.push(new THREE.Vector2(Math.sin(a)*.28,Math.cos(a)*(.07+.10*Math.sin(a)**2)));}const geometry=new THREE.LatheGeometry(profile,24);
   for(let i=0;i<24;i++){const cell=new THREE.Mesh(geometry,material);cell.userData={offset:i/24,phase:i*2.4};group.add(cell);cells.push(cell);}
   const arrow=new THREE.ArrowHelper(new THREE.Vector3(1,0,0),new THREE.Vector3(-3.5,-1.6,0),7,0xf2b766,.28,.17);group.add(arrow);
  }catch{stage.textContent=tr('3D is unavailable on this browser. Audio recording still works.','العرض ثلاثي الأبعاد غير متاح. التسجيل الصوتي يعمل.');}
  function setNarrowed(value){narrowed=value;if(wall){const pos=wall.geometry.attributes.position;for(let i=0;i<pos.count;i++){const k=i*3,z=narrowed?1-.62*Math.exp(-Math.pow(base[k+1]/.85,2)):1;pos.setXYZ(i,base[k]*z,base[k+1],base[k+2]*z);}pos.needsUpdate=true;wall.geometry.computeVertexNormals();pointer.visible=narrowed;}labels();draw();}
 box.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setNarrowed(b.dataset.mode==='narrow'));
 function draw(){if(!renderer||disposed)return;group.rotation.y=Number(slider.value)*Math.PI/180;for(const cell of cells){const u=(cell.userData.offset+time*.16)%1;const x=-3.8+7.6*u,spread=narrowed?1-.62*Math.exp(-Math.pow(x/.85,2)):1;cell.position.set(x,Math.sin(cell.userData.phase)*.55*spread,Math.cos(cell.userData.phase)*.55*spread);cell.scale.setScalar(.7);cell.rotation.set(.5+Math.sin(time+cell.userData.phase)*.3,cell.userData.phase,time*.6);}material.emissiveIntensity=playing?Math.min(.7,signal*2):0;renderer.render(scene,camera);}
  function labels(){box.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='narrow')===narrowed)));box.querySelector('.vessel-callout').textContent=narrowed?'Narrower opening here':'Open passage';box.querySelector('strong').textContent=options.finding!==undefined?(narrowed?tr('Stenosis documented','تضيق موثق'):tr('No stenosis documented','لا تضيق موثق')):tr('Blood movement • cutaway view','حركة الدم • مقطع مفتوح');box.querySelector('.flow-head span').textContent=tr('Educational illustration','رسم تعليمي');button.textContent=preview?tr('Stop preview','إيقاف العرض'):playing&&!frozen?tr('Pause motion','تثبيت الحركة'):playing?tr('Resume motion','تحريك المشهد'):tr('Preview blood movement','شاهد حركة الدم');slider.setAttribute('aria-label',tr('Viewing angle','زاوية العرض'));box.querySelector('label span').textContent=tr('Rotate','تدوير');box.querySelector('p').textContent=options.finding!==undefined?tr('Schematic based on the dataset finding, not reconstructed from sound. Not patient-specific anatomy.','رسم حسب تصنيف المصدر، وليس مستنتجًا من الصوت أو شكلًا تشريحيًا للمريض.'):tr('Manually selected illustration—not inferred from audio. Direction and speed are illustrative.','الاتجاه والسرعة للتوضيح. الصوت يغير الإضاءة، وليس قياسًا لتدفق الدم.');renderer?.domElement.setAttribute('aria-label',tr('Open vessel with red blood cells moving left to right','وعاء مفتوح بخلايا حمراء تتحرك من اليسار لليمين'));}
  function tick(now){frame=0;if(disposed||!preview)return;if(!box.isConnected||box.closest('[hidden]')||document.hidden){preview=false;labels();return;}time+=Math.min((now-last)/1000,.05);last=now;draw();frame=requestAnimationFrame(tick);}
  button.onclick=()=>{if(playing){frozen=!frozen;}else{preview=!preview;cancelAnimationFrame(frame);if(preview){last=performance.now();frame=requestAnimationFrame(tick);}}labels();};slider.oninput=draw;
  const item={update(rms,seconds,on){if(on&&preview){preview=false;cancelAnimationFrame(frame);}const changed=playing!==on;playing=on;signal=rms;if(!frozen&&on)time=seconds;draw();if(changed)labels();},refresh(){labels();draw();},dispose(){disposed=true;cancelAnimationFrame(frame);scene?.traverse(o=>{o.geometry?.dispose();});material?.dispose();renderer?.dispose();box.remove();instances.delete(item);}};
  if(options.finding!==undefined){box.querySelector('.vessel-modes').hidden=true;setNarrowed(options.finding);}instances.add(item);labels();draw();return item;
 }
 new MutationObserver(()=>instances.forEach(s=>s.refresh())).observe(document.documentElement,{attributes:true,attributeFilter:['lang','data-theme']});
 return{create,capture:create(document.querySelector('.live-display').parentElement)};
})();
